size_t ufs4_emmc_sdexpress_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void ufs4_emmc_sdexpress_init(void) {
    g_online = true;
    kprintf("[FS/UFS4-FLASH] UFS 4.0 HS-Gear5 + SD Express PCIe Gen4 + USB4 UAS + S.M.A.R.T. Wear (%lu rules)\n", (unsigned long)ufs4_emmc_sdexpress_db_size());
}

bool ufs4_emmc_sdexpress_selftest(void) {
    return g_online && ufs4_emmc_sdexpress_db_size() >= 3400;
}
